              steps: ['tmsh create ltm profile client-ssl app_clientssl defaults-from clientssl cert-key-chain replace-all-with { app.lab.example { cert app.lab.example.crt key app.lab.example.key } }', 'tmsh create ltm virtual vs_https destination 203.0.113.100:443 pool web_pool profiles add { http app_clientssl } source-address-translation { type automap }'], needs: [0],
