              steps: ['modify ltm rule r_yavas when HTTP_REQUEST { switch -glob -- [HTTP::path] { "/api/*" { pool api_pool } "*.jpg" - "*.png" - "*.css" - "*.js" - "/static/*" { pool static_pool } default { pool web_pool } } }'],
